import React, { useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { DataTable } from "primereact/datatable";
import { Column } from "primereact/column";
import { Button } from "primereact/button";
import { Link } from "react-router-dom";
import {
  fetchEmployees,
  deleteEmployee,
} from "../redux/employee/employeesSlice";

const EmployeeList = () => {
  const dispatch = useDispatch();
  const {
    items: employees,
    status,
    error,
  } = useSelector((state) => state.employees);

  useEffect(() => {
    if (status === "idle") dispatch(fetchEmployees());
  }, [status, dispatch]);

  const handleDelete = (id) => {
    if (window.confirm("Are you sure to delete?")) {
      dispatch(deleteEmployee(id));
    }
  };

  const actionBodyTemplate = (rowData) => (
    <div className="d-flex">
      <Link to={`/edit/${rowData.id}`} className="me-2">
        <Button icon="pi pi-pencil" className="p-button-sm p-button-info" />
      </Link>
      <Button
        icon="pi pi-trash"
        className="p-button-sm p-button-danger"
        onClick={() => handleDelete(rowData.id)}
      />
    </div>
  );

  return (
    <div className="card p-3">
      <div className="d-flex justify-content-between align-items-center mb-3">
        <h3 className="m-0">Employee List</h3>
        <Link to="/add" className="btn btn-primary">
          Add Employee
        </Link>
      </div>

      {status === "loading" && <div>Loading...</div>}
      {status === "failed" && (
        <div className="text-danger">Error: {JSON.stringify(error)}</div>
      )}

      <DataTable
        value={employees}
        paginator
        rows={5}
        responsiveLayout="scroll"
        stripedRows
      >
        <Column field="name" header="Name" sortable />
        <Column field="lastname" header="Last Name" sortable />
        <Column field="email" header="Email" sortable />
        <Column field="position" header="Position" sortable />
        <Column body={actionBodyTemplate} header="Actions" />
      </DataTable>
    </div>
  );
};

export default EmployeeList;
